const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  const scale = 1000;
  const maxPixels = 1e9;

  function getInfoPromise(eeObject) {
    return new Promise((resolve, reject) => {
      eeObject.getInfo((res, err) => (err ? reject(err) : resolve(res)));
    });
  }

  // 1. Geometry & Time Definitions
  const p1 = ee.Geometry.Point([-79.198692, 43.244129]);
  const p2 = ee.Geometry.Point([-79.069485, 43.263113]);
  const buf = 1000; // meters
  const roi1 = p1.buffer(buf);
  const roi2 = p2.buffer(buf);
  const aoi = roi1.union(roi2);

  // 2. Dataset builders
  function buildS2(start, end) {
    const raw = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterDate(start, end)
      .filterBounds(aoi)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 90));
    const processed = raw.map(function(img) {
      const qa = img.select('QA60');
      const mask = qa.bitwiseAnd(1 << 10).eq(0).and(qa.bitwiseAnd(1 << 11).eq(0));
      const scaled = img.updateMask(mask).select(['B2','B3']).multiply(1e-4);
      const ndgb = scaled.normalizedDifference(['B3','B2']).rename('NDGB');
      return ndgb.copyProperties(img, img.propertyNames());
    });
    return {raw, coll: processed, dataset: 'S2_SR', start, end};
  }

  function buildL8(start, end) {
    const raw = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterDate(start, end)
      .filterBounds(aoi);
    const processed = raw.map(function(img){
      const qa = img.select('QA_PIXEL');
      const mask = qa.bitwiseAnd(1 << 5).eq(0) // cloud
        .and(qa.bitwiseAnd(1 << 3).eq(0))      // cloud shadow
        .and(qa.bitwiseAnd(1 << 4).eq(0))      // snow
        .and(img.select('QA_RADSAT').eq(0));   // radiometric saturation
      const refl = img.updateMask(mask).select(['SR_B2','SR_B3']).multiply(0.0000275).add(-0.2);
      const ndgb = refl.normalizedDifference(['SR_B3','SR_B2']).rename('NDGB');
      return ndgb.copyProperties(img, img.propertyNames());
    });
    return {raw, coll: processed, dataset: 'L8_L2', start, end};
  }

  // 3. Try progressive searches
  const tries = [
    buildS2('2021-02-04', '2021-02-05'),
    buildS2('2021-02-01', '2021-02-07'),
    buildL8('2021-02-01', '2021-02-07'),
    buildL8('2021-01-25', '2021-02-13'),
  ];

  let used = null;
  for (let t of tries) {
    const n = await getInfoPromise(t.raw.size());
    if (n > 0) { used = {...t, rawCount: n}; break; }
  }
  if (!used) {
    console.log('No images found in all attempts.');
    console.log('C1');
    return;
  }

  // 4. Composite and compute stats
  const ndgbImg = used.coll.median().select('NDGB');

  async function roiStats(roi) {
    const totalDict = await getInfoPromise(ee.Image.constant(1).rename('ones').reduceRegion({
      reducer: ee.Reducer.count(), geometry: roi, scale: scale, maxPixels: maxPixels
    }));
    const total = (totalDict && (totalDict.ones || totalDict.constant)) ? totalDict.ones || totalDict.constant : 0;

    const countDict = await getInfoPromise(ndgbImg.reduceRegion({
      reducer: ee.Reducer.count(), geometry: roi, scale: scale, maxPixels: maxPixels
    }));
    const valCount = countDict ? (countDict.NDGB || 0) : 0;

    const meanDict = await getInfoPromise(ndgbImg.reduceRegion({
      reducer: ee.Reducer.mean(), geometry: roi, scale: scale, maxPixels: maxPixels
    }));
    const mean = meanDict ? meanDict.NDGB : null;

    return {total: Number(total || 0), valCount: Number(valCount || 0), mean: mean !== null ? Number(mean) : null};
  }

  try {
    const s1 = await roiStats(roi1);
    const s2 = await roiStats(roi2);

    console.log(`Dataset: ${used.dataset}, Window: ${used.start}..${used.end}, Images: ${used.rawCount}`);
    console.log(`P1 valid: ${s1.valCount}/${s1.total} (${s1.total ? (100*s1.valCount/s1.total).toFixed(1) : '0.0'}%), NDGB mean: ${s1.mean !== null ? s1.mean.toFixed(3) : 'null'}`);
    console.log(`P2 valid: ${s2.valCount}/${s2.total} (${s2.total ? (100*s2.valCount/s2.total).toFixed(1) : '0.0'}%), NDGB mean: ${s2.mean !== null ? s2.mean.toFixed(3) : 'null'}`);

    if (s1.valCount === 0 || s2.valCount === 0) {
      console.log('No valid pixels after masking.');
      console.log('C2'); return;
    }

    const invalid = (v) => (v === null || !isFinite(v) || v < -1.0 || v > 1.0);
    if (invalid(s1.mean) || invalid(s2.mean)) {
      console.log('Invalid NDGB values (null/NaN/out of range).');
      console.log('C3'); return;
    }

    const diff = s1.mean - s2.mean;
    console.log(`NDGB diff (P1-P2): ${diff.toFixed(3)}`);

    // Decision: greener if NDGB higher (tolerance 0.005)
    if (diff > 0.005) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (e) {
    console.log(`Error: ${e && e.message ? e.message : e}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
